        this._featureChained = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IFeatureChaining_featureChained, this);
        this._relatedElement = new RequiredMultiContainmentValueManager<Element>(kermlBase.INSTANCE.IRelationship_relatedElement, this);
        this._target = new RequiredMultiContainmentValueManager<Element>(kermlBase.INSTANCE.IRelationship_target, this);
        this._source = new RequiredMultiContainmentValueManager<Element>(kermlBase.INSTANCE.IRelationship_source, this);
