        super(classifier, id, receiveDelta, parentInfo);
        this._relatedType = new RequiredMultiContainmentValueManager<Type>(kermlBase.INSTANCE.IAssociation_relatedType, this);
        this._sourceType = new RequiredMultiContainmentValueManager<Type>(kermlBase.INSTANCE.IAssociation_sourceType, this);
        this._targetType = new RequiredMultiContainmentValueManager<Type>(kermlBase.INSTANCE.IAssociation_targetType, this);
