        this._ownedSubclassification = new RequiredMultiContainmentValueManager<Subclassification>(kermlBase.INSTANCE.IClassifier_ownedSubclassification, this);
        this._ownedFeatureMembership = new RequiredMultiContainmentValueManager<FeatureMembership>(kermlBase.INSTANCE.IType_ownedFeatureMembership, this);
        this._ownedFeature = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_ownedFeature, this);
        this._ownedEndFeature = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_ownedEndFeature, this);
        this._feature = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_feature, this);
        this._input = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_input, this);
        this._output = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_output, this);
        this._isAbstract = new RequiredPropertyValueManager<boolean>(kermlBase.INSTANCE.IType_isAbstract, this);
        this._inheritedMembership = new RequiredMultiContainmentValueManager<Membership>(kermlBase.INSTANCE.IType_inheritedMembership, this);
        this._endFeature = new RequiredMultiContainmentValueManager<Feature>(kermlBase.INSTANCE.IType_endFeature, this);
        this._isSufficient = new RequiredPropertyValueManager<boolean>(kermlBase.INSTANCE.IType_isSufficient, this);
        this._ownedConjugator = new RequiredMultiContainmentValueManager<Conjugation>(kermlBase.INSTANCE.IType_ownedConjugator, this);
