    getPropertyValueManager(property: Property): PropertyValueManager<unknown> {
        switch (property.key) {
            case kermlBase.INSTANCE.ILiteralInteger_value.key: return this._value;
            case kermlBase.INSTANCE.IExpression_isModelLevelEvaluable.key: return this._isModelLevelEvaluable;
            case kermlBase.INSTANCE.IFeature_isUnique.key: return this._isUnique;
            case kermlBase.INSTANCE.IFeature_isOrdered.key: return this._isOrdered;
            case kermlBase.INSTANCE.IFeature_isComposite.key: return this._isComposite;
            case kermlBase.INSTANCE.IFeature_isEnd.key: return this._isEnd;
            case kermlBase.INSTANCE.IFeature_isDerived.key: return this._isDerived;
            case kermlBase.INSTANCE.IFeature_isPortion.key: return this._isPortion;
            case kermlBase.INSTANCE.IFeature_isVariable.key: return this._isVariable;
            case kermlBase.INSTANCE.IFeature_isConstant.key: return this._isConstant;
            case kermlBase.INSTANCE.IFeature_direction.key: return this._direction;
            case kermlBase.INSTANCE.IType_isAbstract.key: return this._isAbstract;
            case kermlBase.INSTANCE.IType_isSufficient.key: return this._isSufficient;
            case kermlBase.INSTANCE.IType_isConjugated.key: return this._isConjugated;
            case kermlBase.INSTANCE.IElement_elementId.key: return this._elementId;
            case kermlBase.INSTANCE.IElement_aliasIds.key: return this._aliasIds;
            case kermlBase.INSTANCE.IElement_declaredShortName.key: return this._declaredShortName;
            case kermlBase.INSTANCE.IElement_declaredName.key: return this._declaredName;
            case kermlBase.INSTANCE.IElement_shortName.key: return this._shortName;
            case kermlBase.INSTANCE.IElement_name.key: return this._name;
            case kermlBase.INSTANCE.IElement_qualifiedName.key: return this._qualifiedName;
            case kermlBase.INSTANCE.IElement_isImpliedIncluded.key: return this._isImpliedIncluded;
            case kermlBase.INSTANCE.IElement_isLibraryElement.key: return this._isLibraryElement;
            default: return super.getPropertyValueManager(property);
        }
    }

